package tsfront

import (
	"bufio"
	"bytes"
	"os"
	"os/exec"
	"path/filepath"
	"strconv"
	"testing"
)

// Opt-in original Node differential. The manifests/oracles are generated by the
// tools documented in testdata/library-incremental; keep large M1 trees outside
// the repository. All child builds inherit the caller's systemd memory scope.
func TestRegistryGoLibraryIncremental(t *testing.T) {
	library := os.Getenv("ABAPITI_LIBRARY_INCREMENTAL_DIR")
	if library == "" {
		t.Skip("set ABAPITI_LIBRARY_INCREMENTAL_DIR, _MANIFEST and _REFERENCE for the full-core differential")
	}
	fresh := os.Getenv("ABAPITI_LIBRARY_INCREMENTAL_FRESH") == "1"
	manifest, reference := os.Getenv("ABAPITI_LIBRARY_INCREMENTAL_MANIFEST"), os.Getenv("ABAPITI_LIBRARY_INCREMENTAL_REFERENCE")
	if manifest == "" || !fresh && reference == "" {
		t.Fatal("manifest and original Node reference (or _FRESH=1) are required")
	}
	library, err := filepath.Abs(library)
	if err != nil {
		t.Fatal(err)
	}
	manifest, err = filepath.Abs(manifest)
	if err != nil {
		t.Fatal(err)
	}
	dir := t.TempDir()
	source, err := os.ReadFile(filepath.Join("testdata", "library-incremental", "dump.go.txt"))
	if err != nil {
		t.Fatal(err)
	}
	mod := "module incrementalfixture\n\ngo 1.26.0\n\nrequire zabaplint v0.0.0\nreplace zabaplint => " + strconv.Quote(library) + "\n"
	for name, raw := range map[string][]byte{"main.go": source, "go.mod": []byte(mod)} {
		if err = os.WriteFile(filepath.Join(dir, name), raw, 0600); err != nil {
			t.Fatal(err)
		}
	}
	binary := filepath.Join(dir, "dump")
	build := exec.Command("go", "build", "-p=1", "-gcflags=-N", "-o", binary, ".")
	build.Dir = dir
	build.Env = append(os.Environ(), "GOWORK=off", "GOPROXY=off")
	if out, err := build.CombinedOutput(); err != nil {
		t.Fatalf("build differential: %v\n%s", err, out)
	}
	actual, err := os.Create(filepath.Join(dir, "actual.jsonl"))
	if err != nil {
		t.Fatal(err)
	}
	defer actual.Close()
	args := []string{manifest}
	if fresh {
		args = append(args, "--fresh")
	}
	command := exec.Command(binary, args...)
	command.Stdout = actual
	var stderr bytes.Buffer
	command.Stderr = &stderr
	if err = command.Run(); err != nil {
		t.Fatalf("differential: %v\n%s", err, stderr.Bytes())
	}
	if _, err = actual.Seek(0, 0); err != nil {
		t.Fatal(err)
	}
	if fresh {
		scan := bufio.NewScanner(actual)
		scan.Buffer(make([]byte, 64*1024), 64*1024*1024)
		lines := 0
		for scan.Scan() {
			lines++
		}
		if err := scan.Err(); err != nil {
			t.Fatal(err)
		}
		if lines == 0 {
			t.Fatal("empty fresh differential")
		}
		t.Logf("%d issue/tree snapshots equal fresh Checkers", lines)
		return
	}

	expected, err := os.Open(reference)
	if err != nil {
		t.Fatal(err)
	}
	defer expected.Close()
	got, want := bufio.NewScanner(actual), bufio.NewScanner(expected)
	for _, scan := range []*bufio.Scanner{got, want} {
		scan.Buffer(make([]byte, 64*1024), 64*1024*1024)
	}
	lines := 0
	for want.Scan() {
		lines++
		if !got.Scan() || !bytes.Equal(got.Bytes(), want.Bytes()) {
			t.Fatalf("snapshot %d differs from original Node", lines)
		}
	}
	if got.Scan() {
		t.Fatal("unexpected trailing snapshot")
	}
	if err = got.Err(); err != nil {
		t.Fatal(err)
	}
	if err = want.Err(); err != nil {
		t.Fatal(err)
	}
	if lines == 0 {
		t.Fatal("empty differential")
	}
	t.Logf("%d byte-identical issue/tree snapshots", lines)
}
